class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def KDistanceNodes(root: TreeNode, target: int, k: int) -> List[int]:
    def dfs(node, parent):
        if node:
            node.parent = parent
            dfs(node.left, node)
            dfs(node.right, node)

    def find_target(node, target):
        if not node:
            return None
        if node.val == target:
            return node
        left = find_target(node.left, target)
        if left:
            return left
        return find_target(node.right, target)

    def collect_k_distance_nodes(node, k, visited, result):
        if not node or node in visited:
            return
        visited.add(node)
        if k == 0:
            result.append(node.val)
            return
        collect_k_distance_nodes(node.left, k - 1, visited, result)
        collect_k_distance_nodes(node.right, k - 1, visited, result)
        collect_k_distance_nodes(getattr(node, 'parent', None), k - 1, visited, result)

    dfs(root, None)
    target_node = find_target(root, target)
    result = []
    collect_k_distance_nodes(target_node, k, set(), result)
    return sorted(result)
